import React, { useCallback, useEffect, useLayoutEffect, useRef, useState } from 'react'

/*
 * FLARE: interactive pitch opening in three slides
 * NASA Space Apps Challenge 2026, "Flame in Freefall", team Cosmic Shihab.
 *
 *   Slide 1  Apollo 1: the three crew members, then the cost.
 *   Slide 2  From spacecraft to fire emergency: one continuous sequence (about 25 s).
 *   Slide 3  The camera finds the flame, the question appears, the flame becomes FLARE (about 12 s).
 *
 * The presenter moves between slides; nothing ever changes the slide by itself. Inside a
 * slide, its sequence plays from the moment the presenter enters it, and the cost on
 * slide 1 also appears by itself after 15 s. Those are reveals within the slide.
 * - Ambient layer: CSS keyframes that always run (stars, Earth, station, astronaut,
 *   floating objects, flame, smoke, warning lights).
 * - Story layer: every visual is derived from the current beat and phase and moved with
 *   CSS transitions, so PREVIOUS returns to the exact earlier state and a click during a
 *   sequence retargets straight to the new slide instead of queueing.
 *
 * Everything is inline SVG except the three official NASA portraits (public domain),
 * embedded as data URIs. The font stacks name the Space Apps brand faces first and fall
 * back to system fonts.
 */

// ============================================================================
// Tweak here
// ============================================================================

