  return { x: -20 - r() * 60, y: -14 + r() * 28, r: 1.6 + r() * 1.6, d: 1.5 + r() * 1.4, delay: -r() * 2.5, ex: -(160 + r() * 140), ey: -24 + r() * 48 }
