const POSES = {
  working: { lean: -4, head: -7, visor: -12, front: 84, back: 18 },
  noticing: { lean: -9, head: 5, visor: 12, front: 36, back: -118 },
  bracing: { lean: -12, head: 9, visor: 13, front: 118, back: -96 },
}

function Arm({ x, y, angle, front = false }) {
  return (
    <g style={{ transform: pivot(angle, x, y), transition: `transform ${TIMING.pose}ms ${TIMING.ease}` }}>
      <path d={`M${x} ${y} C ${x - 4} ${y + 40}, ${x + 4} ${y + 66}, ${x} ${y + 92}`} stroke={front ? COLORS.suit : COLORS.suitShade} strokeWidth="25" strokeLinecap="round" fill="none" />
      <rect x={x - 13} y={y + 74} width="26" height="9" rx="4" fill={COLORS.suitAccent} />
      <circle cx={x} cy={y + 102} r="14" fill={front ? '#C9D6EA' : '#B4C4DE'} />
    </g>
  )
}

/** The one astronaut, used in every scene. Feet at the origin; the pose prop turns it. */
function Astronaut({ pose = 'working' }) {
  const p = POSES[pose] || POSES.working
  const move = `transform ${TIMING.pose}ms ${TIMING.ease}`
  return (
    <g data-astronaut="" data-pose={pose}>
      <g className="fo-amb fo-sway" style={{ '--d': '7.5s' }}>
        <g style={{ transform: pivot(p.lean, 0, 0), transition: move }}>
          <Arm x={22} y={-228} angle={p.back} />
          <rect x="6" y="-262" width="58" height="122" rx="16" fill="#DCE5F3" stroke="#B4C4DE" strokeWidth="3" />
          <rect x="18" y="-246" width="34" height="8" rx="4" fill={COLORS.suitAccent} opacity=".8" />
          <path d="M-20 -128 C -26 -92, -30 -52, -22 -14" stroke={COLORS.suitShade} strokeWidth="30" strokeLinecap="round" fill="none" />
          <path d="M12 -128 C 16 -90, 14 -50, 18 -14" stroke={COLORS.suit} strokeWidth="30" strokeLinecap="round" fill="none" />
          <rect x="-34" y="-78" width="22" height="8" rx="4" fill={COLORS.suitAccent} opacity=".85" />
          <rect x="-40" y="-16" width="36" height="16" rx="7" fill="#C2D0E6" />
          <rect x="2" y="-16" width="36" height="16" rx="7" fill="#D3DEEE" />
          <g transform="translate(-4 -186)">
            <g className="fo-amb fo-breathe" style={{ '--d': '3.6s' }}>
              <rect x="-42" y="-68" width="80" height="136" rx="32" fill={COLORS.suit} stroke={COLORS.suitShade} strokeWidth="3" />
              <rect x="-39" y="38" width="74" height="12" fill={COLORS.suitAccent} />
              <rect x="-34" y="-34" width="34" height="26" rx="5" fill="#C9D6EA" />
              <circle cx="-25" cy="-21" r="3.5" fill={COLORS.suitAccent} />
              <circle cx="-13" cy="-21" r="3.5" fill={COLORS.flameCore} />
              <circle cx="22" cy="-50" r="8" fill={COLORS.suitAccent} />
            </g>
          </g>
          <Arm x={-30} y={-228} angle={p.front} front />
          <g style={{ transform: pivot(p.head, -4, -250), transition: move }}>
            <ellipse cx="-4" cy="-252" rx="34" ry="10" fill="#C9D6EA" />
            <circle cx="-4" cy="-298" r="50" fill={COLORS.suit} stroke={COLORS.suitShade} strokeWidth="3" />
            <g style={{ transform: `translate(${p.visor}px, 0px)`, transition: move }}>
              <ellipse cx="-4" cy="-296" rx="34" ry="30" fill="url(#fo-visor)" stroke="#8FA9D6" strokeWidth="2.5" />
              <path d="M-26 -312 C -20 -322, -8 -326, 4 -324" stroke="#FFFFFF" strokeWidth="5" strokeLinecap="round" fill="none" opacity=".7" />
            </g>
            <rect x="-14" y="-352" width="20" height="8" rx="4" fill="#C9D6EA" />
          </g>
        </g>
      </g>
    </g>
  )
}

/**
 * Microgravity flame: no buoyancy, so it is round and calm, with a blue core (little
 * soot) inside a soft amber glow. Three offset shells wobble slowly so the outline
 * breathes. The "earth" variant is the buoyant teardrop, used only in the comparison.
 */
function Flame({ variant = 'micro' }) {
  if (variant === 'earth') {
    return (
      <g>
        <circle cy="-52" r="78" fill="url(#fo-glow)" opacity=".6" />
        <g className="fo-amb fo-tall" style={{ '--d': '1.8s' }}>
          <path d="M0 -134 C 10 -104, 34 -76, 32 -42 C 30 -14, 16 0, 0 0 C -16 0, -30 -14, -32 -42 C -34 -76, -10 -104, 0 -134 Z" fill="url(#fo-earthflame)" />
          <ellipse cy="-16" rx="20" ry="13" fill="url(#fo-core)" opacity=".9" />
        </g>
      </g>
    )
  }
  return (
    <g>
      <g className="fo-amb fo-glow" style={{ '--d': '4.6s' }}>
        <circle r="74" fill="url(#fo-glow)" />
      </g>
      <g className="fo-amb fo-flick-a" style={{ '--d': '3.2s' }}>
        <ellipse rx="34" ry="30" fill="url(#fo-shell)" />
      </g>
      <g className="fo-amb fo-flick-b" style={{ '--d': '4.4s', '--delay': '-1.3s' }}>
        <ellipse cx="3" cy="-3" rx="30" ry="33" fill="url(#fo-shell)" opacity=".75" />
      </g>
      <g className="fo-amb fo-flick-c" style={{ '--d': '5.8s', '--delay': '-2.6s' }}>
        <ellipse cx="-3" cy="2" rx="32" ry="28" fill="url(#fo-shell)" opacity=".65" />
      </g>
      <g className="fo-amb fo-core" style={{ '--d': '3.7s', '--delay': '-0.8s' }}>
        <ellipse rx="21" ry="20" fill="url(#fo-core)" />
      </g>
    </g>
  )
}

/** The flame plus the emergency stages: heat glow, the run along the rack, embers. */
function Fire({ v }) {
  return (
    <>
      <g data-layer="heat" style={v.heat}>
        <g className="fo-amb fo-glow" style={{ '--d': '1.9s' }}>
          <circle r="150" fill="url(#fo-heat)" />
        </g>
      </g>
      <g data-layer="spread" style={v.fireSpread}>
        {/* one continuous flame front under the flickering tongues */}
        <g className="fo-amb fo-flick-a" style={{ '--d': '2.6s', '--delay': '-0.5s' }}>
          <ellipse cx="-96" cy="2" rx="118" ry="30" fill="url(#fo-shell)" opacity=".8" />
          <ellipse cx="-80" cy="8" rx="92" ry="11" fill="url(#fo-core)" opacity=".55" />
        </g>
        {SPREAD_BLOBS.map((b, i) => (
          <g key={i} transform={`translate(${b.x} ${b.y})`}>
            <g className={`fo-amb ${b.cls}`} style={{ '--d': `${b.d}s`, '--delay': `${b.delay}s` }}>
              <ellipse rx={b.rx} ry={b.ry} fill="url(#fo-shell)" opacity={b.o} />
              <ellipse cy={b.ry * 0.2} rx={b.rx * 0.45} ry={b.ry * 0.45} fill="url(#fo-core)" opacity=".7" />
            </g>
          </g>
        ))}
      </g>
      <g data-layer="embers" style={v.embers}>
        {EMBERS.map((e, i) => (
          <g key={i} transform={`translate(${e.x} ${e.y})`}>
            <circle r={e.r} fill="#FFD9A0" className="fo-amb fo-ember" style={{ '--d': `${e.d}s`, '--delay': `${e.delay}s`, '--ex': `${e.ex}px`, '--ey': `${e.ey}px` }} />
          </g>
        ))}
      </g>
      <Flame />
    </>
  )
}

