function StarLayer({ stars, seconds }) {
  const dots = stars.map((s, i) => (
    <circle
      key={i}
      cx={s.x}
      cy={s.y}
      r={s.r}
      fill={COLORS.hullLight}
      opacity={s.twinkle ? undefined : s.o}
      className={s.twinkle ? 'fo-amb fo-twinkle' : undefined}
      style={s.twinkle ? { '--o': s.o, '--d': `${s.d}s`, '--delay': `${s.delay}s` } : undefined}
    />
  ))
  return (
    <g className="fo-amb fo-drift" style={{ '--d': `${seconds}s` }}>
      <g>{dots}</g>
      <g transform={`translate(${W} 0)`}>{dots}</g>
    </g>
  )
}

