function Defs() {
  return (
    <defs>
      <linearGradient id="fo-sky" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0" stopColor={COLORS.skyTop} />
        <stop offset="1" stopColor={COLORS.skyBottom} />
      </linearGradient>
      <radialGradient id="fo-atmo" gradientUnits="userSpaceOnUse" cx="800" cy="1750" r="1196">
        <stop offset="0.955" stopColor={COLORS.flameCore} stopOpacity="0" />
        <stop offset="0.962" stopColor="#9FC6FF" stopOpacity="0.55" />
        <stop offset="0.978" stopColor={COLORS.flameCore} stopOpacity="0.2" />
        <stop offset="1" stopColor={COLORS.flameCore} stopOpacity="0" />
      </radialGradient>
      <linearGradient id="fo-ocean" gradientUnits="userSpaceOnUse" x1="0" y1="600" x2="0" y2="900">
        <stop offset="0" stopColor="#2D67BC" />
        <stop offset="1" stopColor="#163A78" />
      </linearGradient>
      <radialGradient id="fo-earthshade" gradientUnits="userSpaceOnUse" cx="800" cy="1750" r="1150">
        <stop offset="0.88" stopColor={COLORS.skyTop} stopOpacity="0" />
        <stop offset="1" stopColor={COLORS.skyTop} stopOpacity="0.45" />
      </radialGradient>
      <linearGradient id="fo-solar" x1="0" y1="0" x2="1" y2="1">
        <stop offset="0" stopColor="#2B63C4" />
        <stop offset="1" stopColor="#173F8A" />
      </linearGradient>
      <linearGradient id="fo-module" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0" stopColor="#F4F8FE" />
        <stop offset="1" stopColor="#B8CCEA" />
      </linearGradient>
      <radialGradient id="fo-beacon">
        <stop offset="0" stopColor="#F4F8FF" stopOpacity="0.9" />
        <stop offset="1" stopColor={COLORS.hull} stopOpacity="0" />
      </radialGradient>
      <linearGradient id="fo-ceiling" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0" stopColor="#24427A" />
        <stop offset="1" stopColor="#3D619E" />
      </linearGradient>
      <linearGradient id="fo-floor" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0" stopColor="#355891" />
        <stop offset="1" stopColor="#1C3664" />
      </linearGradient>
      <linearGradient id="fo-wall" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0" stopColor="#93AFD9" />
        <stop offset="1" stopColor="#6F8EC1" />
      </linearGradient>
      <radialGradient id="fo-smoke">
        <stop offset="0" stopColor="#5F6C86" stopOpacity="0.85" />
        <stop offset="0.6" stopColor="#74809A" stopOpacity="0.5" />
        <stop offset="1" stopColor="#74809A" stopOpacity="0" />
      </radialGradient>
      <radialGradient id="fo-haze">
        <stop offset="0" stopColor="#5F6C86" stopOpacity="0.4" />
        <stop offset="1" stopColor="#5F6C86" stopOpacity="0" />
      </radialGradient>
      <radialGradient id="fo-glow">
        <stop offset="0" stopColor={COLORS.fireGlow} stopOpacity="0.55" />
        <stop offset="0.45" stopColor={COLORS.fire} stopOpacity="0.22" />
        <stop offset="1" stopColor={COLORS.fire} stopOpacity="0" />
      </radialGradient>
      <radialGradient id="fo-heat">
        <stop offset="0" stopColor={COLORS.fireGlow} stopOpacity="0.6" />
        <stop offset="0.5" stopColor={COLORS.fire} stopOpacity="0.25" />
        <stop offset="1" stopColor={COLORS.fire} stopOpacity="0" />
      </radialGradient>
      <radialGradient id="fo-shell">
        <stop offset="0" stopColor={COLORS.fireGlow} stopOpacity="0.15" />
        <stop offset="0.6" stopColor={COLORS.fireGlow} stopOpacity="0.6" />
        <stop offset="0.86" stopColor={COLORS.fire} stopOpacity="0.85" />
        <stop offset="1" stopColor={COLORS.fire} stopOpacity="0" />
      </radialGradient>
      <radialGradient id="fo-core">
        <stop offset="0" stopColor="#E3EEFF" />
        <stop offset="0.45" stopColor="#9CC3FF" />
        <stop offset="0.8" stopColor={COLORS.flameCore} />
        <stop offset="1" stopColor={COLORS.flameCore} stopOpacity="0" />
      </radialGradient>
      <radialGradient id="fo-firelight">
        <stop offset="0" stopColor={COLORS.fire} stopOpacity="0.5" />
        <stop offset="0.55" stopColor={COLORS.fire} stopOpacity="0.18" />
        <stop offset="1" stopColor={COLORS.fire} stopOpacity="0" />
      </radialGradient>
      <linearGradient id="fo-redwash" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0" stopColor={COLORS.alarmRed} stopOpacity="0.2" />
        <stop offset="1" stopColor={COLORS.deepRed} stopOpacity="0.12" />
      </linearGradient>
      <linearGradient id="fo-beam" x1="0" y1="0" x2="1" y2="0">
        <stop offset="0" stopColor={COLORS.alarmRed} stopOpacity="0.42" />
        <stop offset="1" stopColor={COLORS.alarmRed} stopOpacity="0" />
      </linearGradient>
      <linearGradient id="fo-beam-back" x1="1" y1="0" x2="0" y2="0">
        <stop offset="0" stopColor={COLORS.alarmRed} stopOpacity="0.42" />
        <stop offset="1" stopColor={COLORS.alarmRed} stopOpacity="0" />
      </linearGradient>
      <radialGradient id="fo-redglow">
        <stop offset="0" stopColor={COLORS.alarmRed} stopOpacity="0.8" />
        <stop offset="1" stopColor={COLORS.alarmRed} stopOpacity="0" />
      </radialGradient>
      <radialGradient id="fo-vignette" cx="0.5" cy="0.5" r="0.75">
        <stop offset="0.55" stopColor={COLORS.letterbox} stopOpacity="0" />
        <stop offset="1" stopColor={COLORS.letterbox} stopOpacity="0.85" />
      </radialGradient>
      <linearGradient id="fo-earthflame" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0" stopColor="#FFE7B0" />
        <stop offset="0.5" stopColor={COLORS.fireGlow} />
        <stop offset="1" stopColor={COLORS.fire} />
      </linearGradient>
      <linearGradient id="fo-visor" x1="0" y1="0" x2="1" y2="1">
        <stop offset="0" stopColor="#13285A" />
        <stop offset="0.6" stopColor="#2B58A8" />
        <stop offset="1" stopColor="#8DB6EE" />
      </linearGradient>
      <clipPath id="fo-port">
        <circle cx={PORT.x} cy={PORT.y} r={PORT.r} />
      </clipPath>
      <clipPath id="fo-earthclip">
        <circle cx="800" cy="1750" r="1150" />
      </clipPath>
      {CREW.map((member, i) => (
        <clipPath key={member.name} id={`fo-portrait-${i}`}>
          <rect x={portraitX(i)} y={PORTRAIT.y} width={PORTRAIT.w} height={PORTRAIT.h} rx="8" />
        </clipPath>
      ))}
    </defs>
  )
}

